{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    by_id = {}
    source_order = {}
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        required = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in required):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        parent = node["parent"]
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(node["symbol"], str):
            raise ValueError("symbol must be a string")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int) or node["depth"] < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        utility = node["utility"]
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(float(utility)):
            raise ValueError("utility must be finite numeric")
        by_id[node_id] = node
        source_order[node_id] = index

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id or parent == node["id"]:
                raise ValueError("invalid parent reference")
            children[parent].append(node["id"])
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("inconsistent node depth")

    visited = set()
    stack = [(root_id, 0)]
    while stack:
        node_id, state = stack.pop()
        if state == 1:
            continue
        if node_id in visited:
            raise ValueError("tree contains a cycle or duplicate reachability")
        visited.add(node_id)
        stack.append((node_id, 1))
        for child_id in reversed(children[node_id]):
            stack.append((child_id, 0))
    if len(visited) != len(nodes):
        raise ValueError("tree must be connected")

    symbols = {node["symbol"] for node in nodes}
    if any(symbol not in symbols for symbol in required_symbols):
        raise ValueError("required symbol is not represented")

    required_set = set(required_symbols)
    retained = set(by_id)
    removed = []
    ordered = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in ordered:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required_set:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        retained.remove(node_id)
        if any(by_id[other_id]["symbol"] == symbol for other_id in retained for symbol in required_set):
            removed.append(node_id)
        else:
            retained.add(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }"}
